/** Internal type. DO NOT USE DIRECTLY. */
type Exact<T extends { [key: string]: unknown }> = { [K in keyof T]: T[K] };
/** Internal type. DO NOT USE DIRECTLY. */
export type Incremental<T> = T | { [P in keyof T]?: P extends ' $fragmentName' | '__typename' ? T[P] : never };
import type { TypedDocumentNode as DocumentNode } from '@graphql-typed-document-node/core';
/** What a customer gives to log in. */
export type LoginInput = {
  /**
   * How the customer should recognise this login in the session list, for
   * example `Chrome on Windows`. Null lets the backend derive it from the
   * user agent.
   */
  device?: string | null | undefined;
  /** The email address, compared without regard to case. */
  email: string;
  /**
   * The password in clear over the encrypted connection. It is compared
   * against the stored hash in constant time.
   */
  password: string;
};

/**
 * Where an order stands. Payment is simulated in this store, so an order is
 * `PAID` from the moment it is placed.
 */
export type OrderStatus =
  /**
   * The order was cancelled and its stock released. No mutation in this
   * schema cancels an order, so this value carries the history of an order
   * a backend cancels outside the API.
   */
  | 'CANCELLED'
  /**
   * The order is recorded, its stock is reserved and it is paid. Every
   * order this store places has this status.
   */
  | 'PAID'
  /**
   * The order is recorded and its stock is reserved, and payment has not
   * been confirmed. No backend in this repository answers with this value.
   * It is in the schema because it is the state a real payment provider
   * would put an order in, so a reader sees where that step goes.
   */
  | 'PLACED';

/**
 * Narrows the catalogue. Every field is optional and the fields that are
 * given all have to hold.
 */
export type ProductFilter = {
  /** Keep only the products in the category with this slug. */
  categorySlug?: string | null | undefined;
  /**
   * When true, keep only the products with a stock above zero. The default
   * is false, because a product with no stock is still shown.
   */
  inStockOnly?: boolean | null | undefined;
  /**
   * Keep only the products whose name contains this text, compared without
   * regard to case. This is the whole of search: there is no full text
   * index and no scoring.
   */
  nameContains?: string | null | undefined;
};

/**
 * The three kinds of promotion code the store knows. A fourth kind is a
 * change to this schema, the seed, the conformance expectations and every
 * backend together.
 */
export type PromotionKind =
  /**
   * A fixed amount off the subtotal, for example five euro with `FIVEOFF`.
   * The discount is never more than the subtotal, so a total never falls
   * below the shipping.
   */
  | 'FIXED_AMOUNT'
  /**
   * Shipping at no charge, for example with `FREESHIP`. The code shows in
   * `Cart.shipping` being zero rather than in a discount amount.
   */
  | 'FREE_SHIPPING'
  /**
   * A percentage off the subtotal, for example ten percent with
   * `WELCOME10`.
   */
  | 'PERCENTAGE';

/**
 * What a customer gives to register. The name and the email address are
 * shown back to the customer, the password never is.
 */
export type RegisterInput = {
  /**
   * The email address, which is normalised to lower case and has to be
   * unique across the store.
   */
  email: string;
  /**
   * The name to greet the customer with and to put on the confirmation
   * mail.
   */
  name: string;
  /**
   * The password in clear over the encrypted connection, at least twelve
   * and at most one hundred and twenty eight characters. It is hashed with
   * Argon2id on arrival and is never stored, logged or answered back.
   */
  password: string;
};

/**
 * Every reason a mutation can refuse, as a value a client switches on. A
 * new code is a change to this schema, the conformance expectations and
 * every backend together, so a client that handles every value today keeps
 * handling every value tomorrow.
 */
export type UserErrorCode =
  /** The cart has no lines, so there is nothing to order. */
  | 'CART_EMPTY'
  /**
   * No line with the given id is in this cart. It is also the answer when
   * the line was already removed, so two tabs cannot remove one line twice.
   */
  | 'CART_LINE_NOT_FOUND'
  /** The promotion code exists and has reached its usage limit. */
  | 'CODE_EXHAUSTED'
  /** The promotion code exists and today falls outside its validity window. */
  | 'CODE_EXPIRED'
  /**
   * The promotion code exists and the cart subtotal is below the minimum
   * the code asks for.
   */
  | 'CODE_MINIMUM_NOT_MET'
  /** No promotion code with that text exists. */
  | 'CODE_UNKNOWN'
  /**
   * The email address and the password together do not match a customer.
   * Login answers this one code whether or not the email address is
   * registered, and takes the same time either way, so the answer tells an
   * attacker nothing about who has an account.
   */
  | 'CREDENTIALS_INVALID'
  /** The email address is not a valid address. */
  | 'EMAIL_INVALID'
  /** A customer with that email address is already registered. */
  | 'EMAIL_TAKEN'
  /**
   * The operation needs a signed in customer and the request carried no
   * valid access token.
   */
  | 'NOT_AUTHENTICATED'
  /**
   * No order with the given id belongs to the signed in customer. The
   * `order` query answers null for that case, because a query carries no
   * payload, so this code is what a mutation that names an order answers
   * with.
   */
  | 'ORDER_NOT_FOUND'
  /**
   * The product has less stock than the quantity that was asked for. How
   * many were available is in `CartPayload.availableStock`, so a client can
   * say how many are left without a second query.
   */
  | 'OUT_OF_STOCK'
  /**
   * The password is longer than one hundred and twenty eight characters,
   * the maximum in `docs/security.md`.
   */
  | 'PASSWORD_TOO_LONG'
  /**
   * The password is shorter than twelve characters, the minimum in
   * `docs/security.md`.
   */
  | 'PASSWORD_TOO_SHORT'
  /** No product with the given id or slug exists. */
  | 'PRODUCT_NOT_FOUND'
  /**
   * The quantity is not a whole number of one or more. A quantity of zero
   * is this error and not a removal: `removeCartLine` removes a line.
   */
  | 'QUANTITY_INVALID'
  /**
   * Too many attempts from this address or for this email address in a
   * short time. Login and register answer this and ask the client to wait.
   */
  | 'RATE_LIMITED'
  /**
   * The refresh token that came with the request is unknown, expired, or
   * was already used. A token that was already used means it leaked, so the
   * whole session family is revoked and every device of that customer has
   * to log in again.
   */
  | 'SESSION_INVALID'
  /**
   * No session with the given id belongs to the signed in customer, so
   * there is nothing to revoke.
   */
  | 'SESSION_NOT_FOUND';

